EvalCaseImportClaim {
  "type": "object",
  "description": "What a converter CLAIMED about one imported case. `exact` is CONVERTER-CLAIMED exact: the converter says it applied a structural mapping rule, cited in `note`. MCPJam has NOT verified semantic equivalence, so user-facing copy must say \"claimed exact\", never \"verified\" or \"accepted\". Claim-only: who approved an approximation, when, and why is a PER-RUN decision frozen on the run (`ImportEligibility.approvedApproximationReceipts`), never stored on the case: an approval that lived on a case would outlive the run it was granted for and the edit that invalidated it. Approval and internal keys are rejected with 400, never stripped.",
  "required": [
    "status"
  ],
  "additionalProperties": false,
  "properties": {
    "status": {
      "type": "string",
      "enum": [
        "exact",
        "approximated",
        "unsupported",
        "unresolved"
      ],
      "description": "`exact`: the converter claims a 1:1 structural mapping, and must cite it in `note`. `approximated`: behaviour was intentionally approximated; a human must approve it for EVERY run. `unsupported`: the source behaviour cannot currently be represented. `unresolved`: a deterministic reference does not resolve against the live target. A selected `unsupported` or `unresolved` case cannot run."
    },
    "sourceCaseKey": {
      "type": "string",
      "minLength": 1,
      "maxLength": 512,
      "description": "The case's identity in the source system, when it had one."
    },
    "note": {
      "type": "string",
      "minLength": 1,
      "maxLength": 2000,
      "description": "Why the status is what it is: the mapping rule cited, or what was lost. REQUIRED when `status` is `exact`."
    }
  }
}
EvalCaseCreateRequest {
  "type": "object",
  "required": [
    "title",
    "steps"
  ],
  "description": "Create one case. `title` and a non-empty `steps` array are both required: a case persisted without executable steps could never run.",
  "properties": {
    "judge": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "enabled": {
          "type": "boolean"
        }
      },
      "nullable": true,
      "description": "Per-case judge override. enabled: false skips goal-completion grading for this case; null clears the override and restores the suite setting."
    },
    "declaredSuiteId": {
      "type": "string",
      "maxLength": 128,
      "description": "The suite file's own `suite.id`, when THIS request is a suite-file sync.\n\nA CI-owned suite (see `EvalSuiteDetail.managedBy`) refuses configuration writes with `409` and `details.reason: \"CI_OWNED_SUITE_READ_ONLY\"`. Naming the suite's own declared id is how the file writing itself is allowed through: the platform permits the write only when the id matches, so naming any other id refuses exactly as loudly as naming none. Omit it for ordinary edits.\n\nPREFER THE `declaredSuiteId` QUERY PARAMETER on this route. This body field still works here, but these request bodies are strict on every Inspector that predates the CI-owned lock, so a body field is a `400` against an older deployment while an unknown query parameter is simply ignored. The MCPJam SDK and CLI send the query parameter."
    },
    "title": {
      "type": "string",
      "minLength": 1
    },
    "id": {
      "type": "string",
      "pattern": "^[A-Za-z0-9_-]{1,128}$",
      "description": "Stable declared id for the case: the id it answers to in a suite file, an import or a CLI argument. Minted for you when omitted, and unique within the suite. Distinct from the `id` on the response, which is the case's platform row id."
    },
    "steps": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/components/schemas/EvalTestStep"
      },
      "description": "REPLACES the case's test definition wholesale when provided."
    },
    "expectedOutput": {
      "type": "string"
    },
    "iterations": {
      "type": "integer",
      "minimum": 1,
      "maximum": 10
    },
    "repetitions": {
      "type": "integer",
      "minimum": 1,
      "maximum": 10,
      "description": "Per-case repetitions; omitted cases inherit the suite default. PER-CASE GRADING ONLY: on a suite decided by the suite-wide accuracy threshold this is a VALIDATION_ERROR naming the criterion change that would make it readable, because that criterion takes the trial count from `iterations` raised to the suite's `minimumIterations` and would never read this. Capped at 10, the same hosted ceiling as `iterations`; the suite-file contract's larger `MAX_REPETITIONS` is what a file may DECLARE, not what a hosted run accepts."
    },
    "passThreshold": {
      "type": "number",
      "minimum": 0,
      "maximum": 1,
      "description": "Per-case pass threshold FRACTION: the share of this case's own iterations that must pass. PER-CASE GRADING ONLY: on a suite decided by the suite-wide accuracy threshold this is a VALIDATION_ERROR, for the same reason as the count: that criterion has one percentage over the whole run and no per-case threshold to override."
    },
    "isNegative": {
      "type": "boolean"
    },
    "scenario": {
      "type": "string"
    },
    "intent": {
      "type": "string",
      "minLength": 1,
      "maxLength": 64,
      "pattern": "^\\S(?:[\\s\\S]*\\S)?$",
      "description": "Optional authored analytics grouping label. Must be already trimmed."
    },
    "kind": {
      "type": "string",
      "enum": [
        "capability",
        "regression"
      ],
      "description": "Authored case kind for the simple editor. Absent means the editor derives it from matchOptions."
    },
    "models": {
      "type": "array",
      "items": {
        "type": "object",
        "required": [
          "model"
        ],
        "properties": {
          "model": {
            "type": "string"
          },
          "provider": {
            "type": "string",
            "description": "Derived from a `provider/model` id when omitted."
          },
          "selection": {
            "allOf": [
              {
                "$ref": "#/components/schemas/RequestedModelSelection"
              }
            ],
            "description": "The saved model choice behind `model` (source, connection, `settings.reasoningEffort`). Must be FOR `model`. On a `models` PATCH an entry that omits `selection` KEEPS the case's existing selection for that model; `null` drops it."
          }
        }
      }
    },
    "matchOptions": {
      "type": [
        "object",
        "null"
      ],
      "description": "Tool-call match options in either vocabulary: public (`toolCallOrder: any|in-order|exact`, `extraToolCalls`, `arguments`) or internal (`toolCallOrder: ignore|superset|strict`, `maxExtraToolCalls`, `argumentMatching`), never both in one object. On update, fields you omit keep their current values. `null` clears the case override and inherits the suite's."
    },
    "checks": {
      "type": [
        "object",
        "null"
      ],
      "description": "`null` clears the case override.",
      "properties": {
        "mode": {
          "type": "string",
          "enum": [
            "inherit",
            "replace",
            "extend"
          ]
        },
        "list": {
          "type": "array",
          "items": {
            "$ref": "#/components/schemas/EvalAssertion"
          }
        }
      }
    },
    "import": {
      "$ref": "#/components/schemas/EvalCaseImportClaim"
    },
    "source": {
      "$ref": "#/components/schemas/EvalCaseSource"
    },
    "suppressedSuiteStandardCheckIds": {
      "$ref": "#/components/schemas/SuppressedSuiteStandardCheckIds",
      "type": "array",
      "items": {
        "type": "string"
      }
    }
  },
  "additionalProperties": false
}
