EvalCasesBatchCreateRequest {
  "type": "object",
  "required": [
    "cases"
  ],
  "description": "Author several cases in one call. Each entry takes the same fields as a single create. The 100-case cap is deliberately smaller than a suite file's 500-case limit, so a maximal file uploads in several calls.",
  "properties": {
    "declaredSuiteId": {
      "type": "string",
      "maxLength": 128,
      "description": "The suite file's own `suite.id`, when THIS request is a suite-file sync.\n\nA CI-owned suite (see `EvalSuiteDetail.managedBy`) refuses configuration writes with `409` and `details.reason: \"CI_OWNED_SUITE_READ_ONLY\"`. Naming the suite's own declared id is how the file writing itself is allowed through: the platform permits the write only when the id matches, so naming any other id refuses exactly as loudly as naming none. Omit it for ordinary edits.\n\nPREFER THE `declaredSuiteId` QUERY PARAMETER on this route. This body field still works here, but these request bodies are strict on every Inspector that predates the CI-owned lock, so a body field is a `400` against an older deployment while an unknown query parameter is simply ignored. The MCPJam SDK and CLI send the query parameter."
    },
    "cases": {
      "type": "array",
      "minItems": 1,
      "maxItems": 100,
      "items": {
        "$ref": "#/components/schemas/EvalCaseCreateRequest"
      }
    },
    "duplicatePolicy": {
      "type": "string",
      "enum": [
        "block",
        "warn",
        "create_anyway"
      ],
      "default": "block",
      "description": "What to do with a case whose definition already matches one in the suite. An unrecognized value coerces to `block` and reports the coercion in the response's `duplicatePolicy` rather than failing the call."
    },
    "overrideReason": {
      "type": "string",
      "minLength": 1,
      "description": "Required by `warn` and `create_anyway`. Recorded on the case's revision."
    }
  },
  "additionalProperties": false
}
