            "description": "Platform case id: the path parameter for the per-case routes."
          },
          "declaredId": {
            "type": "string",
            "description": "The effective declared id. On a replay this is the stored case's, not the one just sent."
          },
          "title": {
            "type": "string"
          },
          "replayed": {
            "type": "boolean",
            "description": "True when an idempotent retry landed on an already-authored case; nothing new was written."
