    "failed": {
      "type": "array",
      "items": {
        "type": "object",
        "required": [
          "index",
          "code",
          "message"
        ],
        "properties": {
          "index": {
            "type": "integer"
          },
          "title": {
            "type": "string"
          },
          "declaredId": {
            "type": "string"
          },
          "code": {
            "type": "string",
            "description": "Stable machine-readable reason.",
            "enum": [
              "INVALID_ITEM",
              "INVALID_CASE_ID",
              "DUPLICATE_CASE_ID",
              "DUPLICATE_IDEMPOTENCY_KEY",
              "IDEMPOTENCY_CONFLICT",
              "DUPLICATE_CONTENT",
              "OVERRIDE_REASON_REQUIRED",
              "INVALID_CASE",
              "INVALID_IMPORT",
              "UNSTORABLE_ITEM",
              "ITEM_TOO_LARGE"
            ]
          },
          "message": {
            "type": "string"
          }
        }
      }
    },
    "duplicatePolicy": {
      "type": "object",
      "required": [
        "effectivePolicy",
        "coerced"
      ],
      "description": "What policy actually applied, so a coercion is never silent.",
      "properties": {
        "requestedPolicy": {
          "type": "string"
        },
        "effectivePolicy": {
          "type": "string"
        },
        "coerced": {
          "type": "boolean"
        }
      }
    },
    "warnings": {
      "type": "array",
      "items": {
        "$ref": "#/components/schemas/EvalCaseWarning"
      }
    }
  }
}
